{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> int:
	var current_xp: int = 40
	var needed_xp: int = 100
	var added_xp: int = 75
	current_xp += added_xp
	if current_xp >= needed_xp:
		current_xp -= needed_xp
	return current_xp
",
   "domanda": "Quanto vale `current_xp` alla fine?",
   "spiegazione": "`current_xp` parte da 40 e diventa 115 con l'aggiunta. Poiché 115 è maggiore o uguale a 100, scatta il blocco `if` che sottrae 100, lasciando 15."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var base_speed: float = 250.0
	var upgrade_bonus: float = 0.1
	var upgrade_count: int = 3
	var final_speed: float = base_speed * (1.0 + upgrade_bonus * upgrade_count)
	return final_speed
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`upgrade_bonus * upgrade_count` fa `0.3`. Sommato a `1.0` dà `1.3`. Moltiplicato per `250.0` (la velocità base), il risultato è `325.0`."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var upgrades: Array[String] = ["damage", "speed", "health", "speed"]
	var active_upgrades: Dictionary = {}
	for up in upgrades:
		active_upgrades[up] = active_upgrades.get(up, 0) + 1
	return str(active_upgrades["speed"])
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Il ciclo conta quante volte compare ogni stringa. 'speed' compare 2 volte nell'array, quindi il dizionario associa a 'speed' il valore `2`. `str()` lo converte nel testo "2"."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var gem_values: Array[int] = [5, 10, 15, 20]
	var total: int = 0
	for val in gem_values:
		if val > 10:
			total += val
	return total
",
   "domanda": "Quanto vale `total` alla fine?",
   "spiegazione": "Il ciclo controlla ogni valore: 5 e 10 vengono saltati perché non sono maggiori di 10. Vengono sommati solo 15 e 20, per un totale di 35."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var current_health: int = 15
	var damage: int = 20
	var result: int = maxi(0, current_health - damage)
	return result
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`current_health - damage` fa `-5`. La funzione `maxi(0, -5)` sceglie il valore più alto tra 0 e -5, che è 0. La vita non può scendere sotto zero."
  }
 ]
